package com.mamtrex.hospital.nutrition;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="diet_orders") public class DietOrder extends BaseEntity { private String patientId; private String dietType; private String restrictions; private String instructions; private String status; protected DietOrder(){} public DietOrder(String patientId, String dietType, String restrictions, String instructions, String status){this.patientId=patientId; this.dietType=dietType; this.restrictions=restrictions; this.instructions=instructions; this.status=status;} public String getPatientId(){return patientId;} public String getDietType(){return dietType;} public String getRestrictions(){return restrictions;} public String getInstructions(){return instructions;} public String getStatus(){return status;} }
